            hi = int(m.group(3) or lo)
            if hi < lo or hi - lo > 40:
                continue
            for w in rule["windows"]:
                if same_file(m.group(1), w["file"]) and lo <= w["end"] + slack and hi >= w["start"] - slack:
                    ok = True
        return ok
    if t == "text":
        if not isinstance(val, str):
            raise ValueError(f"{name}: expected a string")
        v = val.strip()
