            return False
        words = rule.get("any", [])
        return not words or any(w.lower() in v.lower() for w in words)
    raise ValueError(f"unknown rule type {t}")


def main():
    path = SPEC.get("answer_file", "diagnosis.json")
    if not os.path.exists(path):
        finish(0.0, f"{path} not found")
    try:
