    except Exception as e:  # noqa: BLE001
        finish(0.0, f"{path} is not valid JSON: {e}")
    fields = SPEC["fields"]
    if not isinstance(data, dict) or set(data) != set(fields):
        finish(0.0, f"expected an object with exactly the keys {sorted(fields)}")
    ok = 0
